from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.wcdma_rat_reset.classical_wcdma_rat_reset.wcdma_rat_reset_prototype import WcdmaRatReset


class WcdmaRatResetFactory(OperationFactoryPrototype):
    def __init__(self):
        super(WcdmaRatResetFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for WCDMA rat reset operation.
        :return: dictionary with timeout, requirement and operation description for WCDMA rat reset
        :rtype: dict
        """
        return WcdmaRatReset(self.bts).get_kpi()
